// Package migrations embeds the versioned SQL migrations (golang-migrate
// format) so the web and migrate binaries carry them with no files on disk.
//
// Files are generated by `task db:diff NAME=...` from the Ent schema; files
// Ent can't express (PostGIS, extensions, generated columns) are hand-written
// and then re-hashed with `task db:hash`.
package migrations

import "embed"

//go:embed *.sql
var FS embed.FS
